class AdminPromptsPage extends ConsumerStatefulWidget { const AdminPromptsPage({super.key}); @override ConsumerState<AdminPromptsPage> createState() => _AdminPromptsPageState(); }
class _AdminPromptsPageState extends ConsumerState<AdminPromptsPage> {
  String task = 'extract_classify';
  @override Widget build(BuildContext context) { final value = ref.watch(adminPromptsProvider(task)); return AdminGovernanceFrame(title: context.l10n.adminPrompts, action: M24Button(label: context.l10n.adminNewVersion, onPressed: () => _edit(value.value ?? <AdminPrompt>[])), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: <Widget>[SizedBox(width: 260, child: DropdownButtonFormField<String>(value: task, decoration: InputDecoration(labelText: context.l10n.adminTask), items: <String>['extract_classify','extract_values','explain'].map((e) => DropdownMenuItem<String>(value: e, child: Text(e))).toList(), onChanged: (v) => setState(() => task = v ?? task))), const SizedBox(height: 18), value.when(data: (rows) => Column(children: rows.map((p) => _promptCard(p)).toList()), loading: () => const AppLoadingView(), error: (e, s) => AppErrorView(message: '$e'))])); }
  Widget _promptCard(AdminPrompt prompt) => Padding(padding: const EdgeInsets.only(bottom: 12), child: M24Card(child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: <Widget>[Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: <Widget>[Row(children: <Widget>[Text('v${prompt.version}', style: context.m24.text.h3), const SizedBox(width: 10), _PromptStatus(status: prompt.status)]), const SizedBox(height: 8), Text('${context.l10n.adminCreatedBy}: ${prompt.createdBy ?? '-'} · ${adminDate(context, prompt.createdAt)}'), Text('${context.l10n.adminApprovedBy}: ${prompt.approvedBy ?? '-'} · ${adminDate(context, prompt.approvedAt)}'), Text('${context.l10n.adminActivatedAt}: ${adminDate(context, prompt.activatedAt)}'), if (prompt.lastTest != null) InkWell(onTap: () => _showTests(prompt.lastTest!.cases), child: Padding(padding: const EdgeInsets.only(top: 6), child: Text('${context.l10n.adminLastTest}: ${prompt.lastTest!.passed ? context.l10n.adminPassed : context.l10n.adminFailed} · ${adminDate(context, prompt.lastTest!.at)}', style: context.m24.text.label.copyWith(color: context.m24.colors.primary))))])), AdminPromptActions(prompt: prompt, onApprove: () => _approve(prompt), onTest: () => _test(prompt), onActivate: () => _activate(prompt), onCompare: () => _compare(prompt), onRestore: () => _restore(prompt))])));
  Future<void> _approve(AdminPrompt p) async { try { final result = await ref.read(adminRepositoryProvider).approvePrompt(p.id); _message(result.contains('second_approver_required') ? context.l10n.adminSecondApproverRequired : context.l10n.adminSaved); ref.invalidate(adminPromptsProvider(task)); } catch (e) { _message('$e'); } }
  Future<void> _test(AdminPrompt p) async { try { final cases = await ref.read(adminRepositoryProvider).testPrompt(p.id); if (mounted) await _showTests(cases); ref.invalidate(adminPromptsProvider(task)); } catch (e) { _message('$e'); } }
  Future<void> _activate(AdminPrompt p) async { try { await ref.read(adminRepositoryProvider).activatePrompt(p.id); ref.invalidate(adminPromptsProvider(task)); } on PostgrestException catch (e) { _message(e.message.contains('approval_required') ? context.l10n.adminApprovalRequired : e.message.contains('passing_test_required') ? context.l10n.adminPassingTestRequired : e.message); } }
  Future<void> _restore(AdminPrompt p) async { if (await _confirm(context.l10n.adminRestoreConfirm) != true) return; await ref.read(adminRepositoryProvider).rollbackPrompt(p.taskId); ref.invalidate(adminPromptsProvider(task)); }
  Future<void> _showTests(List<AdminDryRunCase> cases) => showDialog<void>(context: context, builder: (c) => AlertDialog(title: Text(c.l10n.adminTestResults), content: SizedBox(width: 700, child: SingleChildScrollView(child: AdminDryRunResults(cases: cases))), actions: <Widget>[TextButton(onPressed: () => c.pop(), child: Text(c.l10n.commonClose))]));
  Future<void> _edit(List<AdminPrompt> prompts) => showDialog<void>(context: context, builder: (c) => AdminSidePanel(child: AdminPromptEditor(task: task, source: prompts.where((p) => p.status == 'active').firstOrNull, onSave: (system, user, schema, notes) async { await ref.read(adminRepositoryProvider).createPrompt(task: task, systemPrompt: system, userTemplate: user, toolSchema: schema, notes: notes); ref.invalidate(adminPromptsProvider(task)); if (c.mounted) c.pop(); })));
  Future<void> _compare(AdminPrompt prompt) { final rows = ref.read(adminPromptsProvider(task)).value ?? <AdminPrompt>[]; final other = rows.where((p) => p.id != prompt.id).firstOrNull; return showDialog<void>(context: context, builder: (c) => AlertDialog(title: Text(c.l10n.adminCompare), content: SizedBox(width: 900, height: 600, child: AdminPromptComparison(left: prompt, right: other ?? prompt)), actions: <Widget>[TextButton(onPressed: () => c.pop(), child: Text(c.l10n.commonClose))])); }
  Future<bool?> _confirm(String text) => showDialog<bool>(context: context, builder: (c) => AlertDialog(content: Text(text), actions: <Widget>[TextButton(onPressed: () => c.pop(false), child: Text(c.l10n.commonCancel)), TextButton(onPressed: () => c.pop(true), child: Text(c.l10n.commonConfirm))]));
  void _message(String text) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text))); }
}

